<div class="panel appointments-panel" data-reveal><div class="panel-heading"><div><span class="eyebrow">LO QUE SIGUE</span><h2>Próximas citas</h2><p>Visitas futuras dentro del período seleccionado</p></div><?php if($allowed['appointments']): ?><a class="text-link" href="<?= e(url('/admin/appointments')) ?>">Ver agenda <?= icon('arrow',15) ?></a><?php endif; ?></div><?php if($upcoming): ?><div class="schedule-list"><?php foreach($upcoming as $a): ?><button class="schedule-item" type="button" data-movement="appointment:<?= (int)$a['id'] ?>"><span class="schedule-hour"><?= local_date($a['starts_at'],'H:i') ?><small><?= local_date($a['starts_at'],'d/m') ?></small></span><span class="schedule-person"><strong><?= e($a['patient']) ?></strong><small><?= e($a['service']) ?> · <?= e($a['dentist'] ?: 'Por asignar') ?></small></span><?= badge($a['status']) ?><?= icon('arrow',16) ?></button><?php endforeach; ?></div><?php else: ?><div class="empty"><?= icon('calendar',32) ?><p><?= $allowed['appointments'] ? 'No hay próximas citas en este período. Cambia las fechas o registra una visita.':'Tu rol no tiene acceso al detalle de la agenda.' ?></p><?php if($allowed['appointments']): ?><a href="<?= e(url('/admin/appointments?new=1')) ?>" class="text-link">Agendar una visita <?= icon('arrow',15) ?></a><?php endif; ?></div><?php endif; ?></div>
